{
  "summary": "Manager Nina Orlova called the bakery 'Kolos' regarding an invoice for an exhaust fan order. The customer wanted to pay by card immediately and provided card details over the phone. Nina confirmed the fan is in stock, promised shipment tomorrow with delivery Friday or Monday, and agreed to send shipping confirmation and contractor contacts by end of day.",
  "customer_need": "Pay invoice by card and get delivery timeline for exhaust fan NW-RF-400E.",
  "outcome": "follow_up",
  "next_step": {
    "action": "Send shipping confirmation and contractor contacts",
    "due": "2026-10-14",
    "owner": "manager"
  },
  "criteria": {
    "greeting": {
      "score": 2,
      "evidence": ["U2"],
      "comment": "Manager greeted customer by name, introduced herself and company, and stated the reason for the outbound call."
    },
    "discovery": {
      "score": 0,
      "evidence": ["U2"],
      "comment": "Manager did not ask any discovery questions about application, size, airflow, constraints, or deadline; the call was about an existing order."
    },
    "recommendation": {
      "score": 1,
      "evidence": ["U8"],
      "comment": "Manager named the product NW-RF-400E but did not tie it to any customer needs as the order was already placed."
    },
    "objections": {
      "score": null,
      "evidence": [],
      "comment": "No objections raised about price, lead time, or need."
    },
    "closing": {
      "score": 2,
      "evidence": ["U14"],
      "comment": "Manager agreed to send shipping confirmation and contractor contacts by end of day today (2026-10-14), a concrete next action with owner and date."
    },
    "listening": {
      "score": 2,
      "evidence": ["U2", "U4", "U6", "U8", "U10", "U12", "U14"],
      "comment": "Manager let customer finish, responded politely, confirmed details."
    },
    "compliance": {
      "score": 0,
      "evidence": ["U4", "U5"],
      "comment": "Manager requested and accepted card details over the phone, violating policy against taking payment data over the phone."
    }
  },
  "red_flags": [
    {
      "type": "payment_data",
      "utterance": "U4",
      "note": "Manager asked customer to dictate card number over the phone."
    }
  ],
  "coaching": "Avoid taking card details over the phone; direct customer to secure payment portal or follow company policy for payment processing."
}

{
  "summary": "Anna Novak from Northwind Air called Grace Lin at Riverton Sports Centre to follow up on a ventilation quote for three roof fans needed by the October 26 half-term closure. The originally quoted NW-RF-315E fans are on 4-6 week backorder, so Anna offered two alternatives: in-stock NW-RF-400E fans (larger, EC motor, $1,000 more total) or splitting the installation. Grace asked Anna to seek a partial price concession from her head of sales; Anna will call back tomorrow before noon with an answer and updated quote.",
  "customer_need": "Three roof fans for changing room ventilation, installed during half-term closure starting 2026-10-26; original quote fans are on backorder.",
  "outcome": "follow_up",
  "next_step": {
    "action": "Manager calls customer with head-of-sales decision on price sharing and an updated quote",
    "due": "2026-10-15",
    "owner": "manager"
  },
  "criteria": {
    "greeting": {
      "score": 2,
      "evidence": ["U2"],
      "comment": "Names company (Northwind Air), herself (Anna Novak), and the reason for the call (changing room ventilation) on this outbound call."
    },
    "discovery": {
      "score": 1,
      "evidence": ["U4"],
      "comment": "Only confirms the previous plan (three roof fans, half-term closure deadline). Does not ask about application details, required airflow, noise constraints, controls, or existing ductwork before recommending."
    },
    "recommendation": {
      "score": 2,
      "evidence": ["U6", "U8"],
      "comment": "Recommends two specific options (NW-RF-400E in stock, or split installation with NW-RF-315E) and ties each to the customer's deadline and airflow needs."
    },
    "objections": {
      "score": 2,
      "evidence": ["U7", "U9", "U10"],
      "comment": "Addresses price difference ($335/fan) and contractor double-payment concern with facts, offers the split-work alternative, and proposes asking head of sales to share the cost difference without promising an unapproved discount."
    },
    "closing": {
      "score": 2,
      "evidence": ["U12"],
      "comment": "Agrees a concrete next step: manager will ask head of sales today and call back tomorrow before 12:00 with answer and updated quote."
    },
    "listening": {
      "score": 2,
      "evidence": ["U6", "U10"],
      "comment": "Lets customer finish, acknowledges points (\"You're right\", \"That's fair\"), stays polite and patient throughout."
    },
    "compliance": {
      "score": 2,
      "evidence": ["U10", "U12"],
      "comment": "No discount offered without approval (explicitly says cannot promise before approval), delivery promise aligns with stock status (NW-RF-400E in stock, ships next business day), no card details taken."
    }
  },
  "red_flags": [],
  "coaching": "On follow-up calls, still ask a few targeted discovery questions (e.g., required airflow, noise limits, duct constraints) to verify the original spec hasn't changed before recommending alternatives."
}

{
  "summary": "Leo Grant (manager) took an inbound call from Hannah Price of Greenway Schools, who needs ventilation for six classrooms with high CO2 levels in a 1960s building. Leo immediately recommended rectangular duct fans (sixty-thirties) without asking key discovery questions, interrupted the customer twice, and agreed the next step is for the customer to send drawings to email, but no date was set.",
  "customer_need": "Ventilation for six classrooms in a 1960s building to reduce CO2 levels, using existing ductwork if possible.",
  "outcome": "quote_requested",
  "next_step": {
    "action": "Customer sends drawings to email for review",
    "due": null,
    "owner": "customer"
  },
  "criteria": {
    "greeting": {
      "score": 2,
      "evidence": ["U1"],
      "comment": "Manager named company and self at start."
    },
    "discovery": {
      "score": 0,
      "evidence": ["U3"],
      "comment": "Manager did not ask any discovery questions about application, size, constraints, or deadline before recommending."
    },
    "recommendation": {
      "score": 2,
      "evidence": ["U3", "U7", "U11"],
      "comment": "Manager recommended specific product (sixty-thirties) with reasons tied to customer's mention of classrooms and old building."
    },
    "objections": {
      "score": 1,
      "evidence": ["U9"],
      "comment": "Manager handled site visit objection by offering alternative (send drawings), but interrupted other concerns."
    },
    "closing": {
      "score": 1,
      "evidence": ["U12", "U13"],
      "comment": "Next step agreed (customer sends drawings) but no date specified."
    },
    "listening": {
      "score": 0,
      "evidence": ["U5", "U7"],
      "comment": "Manager repeatedly interrupted customer and was dismissive ('Trust me')."
    },
    "compliance": {
      "score": 2,
      "evidence": [],
      "comment": "No policy violations observed."
    }
  },
  "red_flags": [
    {
      "type": "rudeness",
      "utterance": "U5",
      "note": "Manager interrupts customer and says 'Trust me' dismissively"
    },
    {
      "type": "rudeness",
      "utterance": "U7",
      "note": "Manager interrupts customer again before they finish asking question"
    }
  ],
  "coaching": "Let the customer finish speaking and ask discovery questions (e.g., deadline, noise constraints, controls) before making a recommendation."
}

{
  "summary": "Nina Orlova from Northwind Air called Golden Crust Bakery about an invoice for a bakery extract fan. The customer wanted to pay by card immediately to expedite delivery. The manager took card details over the phone, confirmed the fan is in stock, promised delivery Friday or Monday, and agreed to send shipping confirmation and installer contacts by end of day.",
  "customer_need": "Pay invoice by card to expedite delivery of bakery extract fan.",
  "outcome": "order",
  "next_step": {
    "action": "Send shipping confirmation and installer contacts",
    "due": "2026-10-14",
    "owner": "manager"
  },
  "criteria": {
    "greeting": {
      "score": 2,
      "evidence": ["U2"],
      "comment": "Manager greeted the customer, named the company (Northwind Air), introduced herself (Nina), and stated the reason for the outbound call (about the order for the bakery extract fan and invoice sent yesterday)."
    },
    "discovery": {
      "score": 0,
      "evidence": [],
      "comment": "Manager asked no discovery questions about application, size, airflow, constraints, or deadline. The call was a follow-up on an existing order, but no needs discovery was performed."
    },
    "recommendation": {
      "score": 0,
      "evidence": ["U8"],
      "comment": "Manager mentioned the product (NW-RF-400E fan) and its stock status, but this was not a recommendation tied to customer needs; it was confirmation of an already ordered item."
    },
    "objections": {
      "score": null,
      "evidence": [],
      "comment": "Customer raised no concerns about price, lead time, or need. The only request was to pay by card to speed up payment, which is not an objection about the product or service."
    },
    "closing": {
      "score": 2,
      "evidence": ["U12", "U14"],
      "comment": "Manager agreed a concrete next action: send shipping confirmation and installer contacts by tonight (2026-10-14), confirmed the on-site contact person (customer herself), and specified who does it (manager) and when (today)."
    },
    "listening": {
      "score": 2,
      "evidence": ["U2", "U8", "U10", "U12", "U14"],
      "comment": "Manager let the customer finish each utterance, confirmed details (delivery contact, payment), stayed polite and patient throughout."
    },
    "compliance": {
      "score": 0,
      "evidence": ["U4", "U5"],
      "comment": "Manager took card details over the phone (U4: 'read me the card number', U5: customer provided card number and details), violating the policy prohibition on taking payment data over the phone."
    }
  },
  "red_flags": [
    {
      "type": "payment_data",
      "utterance": "U4",
      "note": "Manager asked customer to read card number over the phone, and customer provided card details in U5."
    }
  ],
  "coaching": "Do not take card details over the phone; direct customers to the secure payment portal or approved payment process."
}
